def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def native(x):
 if isinstance(x,np.generic): return x.item()
 if isinstance(x,np.ndarray): return x.tolist()
 if isinstance(x,dict): return {k:native(v) for k,v in x.items()}
 if isinstance(x,(tuple,list)): return [native(v) for v in x]
 return x
def dump(name,obj): OUT.mkdir(parents=True,exist_ok=True); (OUT/name).write_text(json.dumps(native(obj),indent=2,sort_keys=True,allow_nan=False)+'\n')
def save(name,**obj): OUT.mkdir(parents=True,exist_ok=True);np.savez_compressed(OUT/name,**obj)
def sign_class(x):
 p=np.any(x>0); n=np.any(x<0)
 return 'MIXED' if p and n else 'RESTORING' if p else 'DESTABILIZING' if n else 'ZERO'
def response_class(values):
 # J is force/displacement: negative directional curvature restores.
 neg=np.all(values<0,axis=-1); pos=np.all(values>0,axis=-1)
 return 'TWO_DOF_RESTORING' if np.all(neg) else 'MIXED_RESTORING_DESTABILIZING' if np.any(neg)&np.any(pos) else 'ONE_DOF_RESTORING' if np.any(values<0) else 'ZERO'
